 for(const band of state.instruments.ruler.ranges||[]){if(band.visible!==false){const from=band.fromM/factor(state.settings.unit),to=band.toM/factor(state.settings.unit);if(from<range){const x=toPx(from),end=toPx(Math.min(to,range));svg+=`<rect class="ruler-range-band" x="${x}" y="20" width="${Math.max(0,end-x)}" height="38" fill="${band.color}" fill-opacity=".4"/>`}}}
 for(let i=0;i*interval/5<=range&&i<150;i++){const value=i*interval/5,x=toPx(value),major=i%5===0;svg+=`<line x1="${x}" y1="20" x2="${x}" y2="${major?43:31}" stroke="#fff0c6" stroke-width="${major?1.2:.7}"/>`;if(major)svg+=`<text x="${x}" y="57" text-anchor="middle" fill="#fff0c6" font-size="11" font-family="monospace">${value.toFixed(Math.min(6,decimals))}</text>`}
