function drawProtractor(){let svg='<circle cx="170" cy="170" r="166" fill="#10253115" stroke="#fff0c6"/><circle cx="170" cy="170" r="119" fill="none" stroke="#fff0c660"/>';for(const angleRange of state.instruments.protractor.ranges||[]){if(angleRange.visible!==false){const arc=angleSector(angleRange.from,angleRange.to);svg+=arc?`<path class="protractor-range-band" d="${arc}" fill="${angleRange.color}" fill-opacity=".3"/>`:`<circle class="protractor-range-band" cx="170" cy="170" r="118" fill="${angleRange.color}" fill-opacity=".3"/>`}}for(let d=0;d<360;d++){const a=rad(d),inner=d%10===0?147:d%5===0?153:158;svg+=`<line x1="${170+inner*Math.sin(a)}" y1="${170-inner*Math.cos(a)}" x2="${170+163*Math.sin(a)}" y2="${170-163*Math.cos(a)}" stroke="#fff0c6" stroke-width="${d%10===0?1.3:.7}"/>`;if(d%10===0)svg+=`<text x="${170+134*Math.sin(a)}" y="${170-134*Math.cos(a)}" text-anchor="middle" dominant-baseline="central" font-family="monospace" font-size="11" fill="#fff0c6">${d}°</text>`}svg+='<path d="M170 10V330M10 170H330" stroke="#fff0c6" stroke-width=".8" stroke-dasharray="4 5"/><circle cx="170" cy="170" r="5" fill="none" stroke="#fff0c6"/>';$('protractor-svg').innerHTML=svg}
