function updateInstrumentControls(){const angleRange=state.instruments.protractor.range;if(angleRange){$('angle-from').value=angleRange.from;$('angle-to').value=angleRange.to;$('angle-color').value=angleRange.color}$('ruler-visible').checked=state.instruments.ruler.visible;$('protractor-visible').checked=state.instruments.protractor.visible;$('ruler-badge').textContent=state.instruments.ruler.visible?'設定範圍':'開啟';$('protractor-badge').textContent=state.instruments.protractor.visible?'設定':'開啟';$('ruler-rotation').value=Number(state.instruments.ruler.rotation.toFixed(2));$('protractor-rotation').value=Number(state.instruments.protractor.rotation.toFixed(2));$('unit-status').textContent=state.settings.unit.toUpperCase();$('range-unit').textContent=state.settings.unit.toUpperCase();const range=state.instruments.ruler.range;if(range){$('range-from').value=Number((range.fromM/factor(state.settings.unit)).toFixed(6));$('range-to').value=Number((range.toM/factor(state.settings.unit)).toFixed(6));$('range-color').value=range.color}}
