function lowerLeftLabel(points,width,height){const ys=points.map(p=>p.y),minY=Math.min(...ys),maxY=Math.max(...ys);const spans=y=>{const xs=[];for(let i=0,j=points.length-1;i<points.length;j=i++){const a=points[j],b=points[i];if((a.y>y)!==(b.y>y))xs.push(a.x+(y-a.y)*(b.x-a.x)/(b.y-a.y))}xs.sort((a,b)=>a-b);return xs.reduce((a,x,i)=>{if(i%2===0)a.push([x,xs[i+1]]);return a},[])};for(let bottom=maxY-5;bottom-height>minY;bottom-=3){let intervals=spans(bottom);const levels=[bottom-height,...ys.filter(y=>y>bottom-height&&y<bottom).flatMap(y=>[y-.01,y+.01])];for(const y of levels){const next=[];for(const [a,b]of intervals)for(const [c,d]of spans(y)){const l=Math.max(a,c),r=Math.min(b,d);if(r-l>=width+10)next.push([l,r])}intervals=next}if(intervals.length)return {x:intervals[0][0]+5,y:bottom-height}}return null}
