function applyRouteOpacity(){routeLines.eachLayer(l=>{const name=[...routePaths].find(([,v])=>v===l)?.[0],prefs=state.settings.routeStyles?.[name]||{};l.setStyle({opacity:clampOpacity(state.settings.routeOpacity)*(prefs.opacity??1),color:prefs.color||state.settings.routeColor||'#6ed7bd'});if(state.settings.routeNames)l.bindTooltip(l.getPopup()?.getContent()?.querySelector('b')?.textContent||'',{permanent:true})});fixes.eachLayer(l=>l.setStyle?.({opacity:clampOpacity(state.settings.fixOpacity),fillOpacity:clampOpacity(state.settings.fixOpacity)}))}
