function updateOpacityInputs(){for(const [panel,key,label,apply] of [['basemap-panel','baseOpacity','底圖',applyBasemapOpacity],['routes-panel','routeOpacity','航路',applyRouteOpacity],['waypoints-panel','fixOpacity','航點',()=>waypointPicker.renderMap()]]){let mount=$(key+'-control');if(!mount){mount=document.createElement('div');mount.id=key+'-control';$(panel).querySelector('.section-body').prepend(mount)}mount.replaceChildren(opacityControl(label,state.settings[key],v=>{snapshot();state.settings[key]=v;apply();save()}));if(key!=='baseOpacity'){const setting={name:label,names:state.settings[key==='routeOpacity'?'routeNames':'fixNames']!==false,color:state.settings[key==='routeOpacity'?'routeColor':'fixColor']||'#75dfc8'};mount.append(layerStyle(setting,()=>{state.settings[key==='routeOpacity'?'routeNames':'fixNames']=setting.names;state.settings[key==='routeOpacity'?'routeColor':'fixColor']=setting.color;renderRoutes();waypointPicker.renderMap();save()}))}}for(const ref of references){const el=[...$('reference-list').children].find(n=>n.querySelector('label')?.textContent===ref.name);if(el&&!el.querySelector('.reference-style')){state.settings.referenceStyles||={};const prefs=state.settings.referenceStyles[ref.id]||={name:ref.name,names:false,color:ref.color};const row=layerStyle(prefs,()=>{applyReferenceOpacity();save()},ref.type==='polygon'?'split':'single');row.classList.add('reference-style');el.append(row)}}}
